import * as T from './three.module.js';import {clone} from './vendor/SkeletonUtils.js';import {fitRig,matteMaterials} from './model-rig.js';import {smoothRig,subdivide} from './smooth-rig.js';import {applyAnimalCoat,coatFor} from './coat-variants.js';import {batchRigidDetails} from './rigid-details.js';
export function groomSurface(){const n=128,data=new Uint8Array(n*n*4);let seed=19271;for(let y=0;y<n;y++)for(let x=0;x<n;x++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const v=118+((seed>>>24)%25)+Math.sin(y*2+x*.18)*5,i=(y*n+x)*4;data.set([v,v,v,255],i);}const m=new T.DataTexture(data,n,n);m.wrapS=m.wrapT=T.RepeatWrapping;m.repeat.set(7,7);m.needsUpdate=true;return m;}
export function createShowHorse(asset,{key='showcase',coat='bay-star',detail=true}={}){const root=new T.Group(),model=clone(asset.scene);root.add(model);smoothRig(model);fitRig(model,2.65);matteMaterials(model);root.updateMatrixWorld(true);let sculpted=0;
 // A local anatomy pass preserves skin weights and authored joints. Added volume is bounded to centimetres.
 model.traverse(o=>{if(!o.isSkinnedMesh||!/^Main$/i.test(o.material.name))return;let g=o.geometry.clone();if(detail)g=subdivide(g);const pos=g.attributes.position,p=new T.Vector3(),inverse=o.matrixWorld.clone().invert();for(let i=0;i<pos.count;i++){p.fromBufferAttribute(pos,i).applyMatrix4(o.matrixWorld);const shoulder=Math.exp(-((p.y-1.43)**2/.12+(p.z-.48)**2/.18)),haunch=Math.exp(-((p.y-1.46)**2/.13+(p.z+.61)**2/.13)),chest=Math.exp(-((p.y-1.15)**2/.1+(p.z-.65)**2/.13));const amount=.035*shoulder+.045*haunch+.025*chest;if(Math.abs(p.x)>.08&&Math.abs(p.x)<.65){p.x+=Math.sign(p.x)*amount;sculpted++;}p.applyMatrix4(inverse);pos.setXYZ(i,p.x,p.y,p.z);}g.computeVertexNormals();g.computeBoundingSphere();o.geometry=g;});
 applyAnimalCoat(model,'horse',key,coat);const hide=groomSurface();model.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){m.roughness=/hair|hooves/i.test(m.name)?.72:.58;m.metalness=0;m.envMapIntensity=.45;if(!/eye|hair/i.test(m.name)){m.bumpMap=hide;m.bumpScale=.006;}m.needsUpdate=true;}o.castShadow=true;o.receiveShadow=true;});
 const palette=coatFor('horse',key,coat),hair=new T.MeshStandardMaterial({color:palette.mane,roughness:.78}),leather=new T.MeshStandardMaterial({color:'#352b24',roughness:.68}),metal=new T.MeshStandardMaterial({color:'#aeb3ad',metalness:.78,roughness:.26}),nostril=new T.MeshStandardMaterial({color:'#302b29',roughness:.83});let added=0;
 function attach(mesh,bone){root.add(mesh);root.updateMatrixWorld(true);const b=model.getObjectByName(bone);if(b)b.attach(mesh);added++;return mesh;}
 function strand(points,r,bone,mat=hair){const g=new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),detail?14:8,r,detail?5:4,false);return attach(new T.Mesh(g,mat),bone);}
 // Individual curved clumps follow their local neck/tail bones without a second skin-transfer system.
 for(let i=0;i<(detail?28:16);i++){const t=i/(detail?27:15),y=1.74+t*.52,z=.68+t*.38;strand([[0,y,z],[-.035,y-.02,z-.07],[-.07-Math.sin(i*2)*.02,y-.17-.07*Math.sin(i),z-.14]],.009,'Neck'+(t<.33?'1':t<.7?'2':'3'));}
 for(let i=0;i<(detail?18:10);i++){const x=Math.sin(i*2.4)*.075;strand([[x,1.78,-.90],[x*1.3,1.44,-1.20],[x*1.8,.85,-1.22],[x*2,.62+Math.sin(i)*.035,-1.19]],.008,'Tail3');}
 for(const side of [-1,1]){const n=new T.Mesh(new T.SphereGeometry(1,16,10),nostril);n.position.set(side*.086,1.985,1.85);n.scale.set(.024,.015,.014);attach(n,'Head');strand([[side*.17,2.30,1.40],[side*.13,2.13,1.70],[side*.09,1.97,1.86]],.018,'Head',leather);const ring=new T.Mesh(new T.TorusGeometry(.047,.008,8,20),metal);ring.position.set(side*.10,1.97,1.85);ring.rotation.y=Math.PI/2;attach(ring,'Head');}
 strand([[-.09,1.99,1.86],[0,1.97,1.90],[.09,1.99,1.86]],.018,'Head',leather);strand([[-.18,2.32,1.41],[0,2.36,1.39],[.18,2.32,1.41]],.016,'Head',leather);
 for(const name of ['Neck1','Neck2','Neck3','Tail3','Head']){const b=model.getObjectByName(name);if(b)batchRigidDetails(b);}const mixer=new T.AnimationMixer(model),actions=new Map(asset.animations.map(c=>[c.name.toLowerCase().split('|').pop(),mixer.clipAction(c)]));let action=null;root.userData={sculptedVertices:sculpted,detailClumps:added,permanentCoat:coat};return {root,model,mixer,actions,update(dt,motion='idle'){const next=actions.get(motion==='walk'?'walk':motion==='gallop'?'gallop':'idle')||actions.get('idle');if(next!==action){action?.fadeOut(.25);next?.reset().fadeIn(.25).play();action=next;}if(action)action.timeScale=motion==='walk'?.68:.86;mixer.update(dt);return action?(action.time/action.getClip().duration)%1:0;}};}

// Unmodified source geometry provides a fair same-coat, same-light comparison.
export function createReferenceHorse(asset,{key='showcase',coat='bay-star'}={}){
 const root=new T.Group(),model=clone(asset.scene);root.add(model);fitRig(model,2.65);matteMaterials(model);applyAnimalCoat(model,'horse',key,coat);
 const mixer=new T.AnimationMixer(model),actions=new Map(asset.animations.map(c=>[c.name.toLowerCase().split('|').pop(),mixer.clipAction(c)]));let action=null;
 return {root,model,mixer,update(dt,motion='idle'){const next=actions.get(motion==='walk'?'walk':motion==='gallop'?'gallop':'idle')||actions.get('idle');if(next!==action){action?.fadeOut(.25);next?.reset().fadeIn(.25).play();action=next;}if(action)action.timeScale=motion==='walk'?.68:.86;mixer.update(dt);return action?(action.time/action.getClip().duration)%1:0;}};
}
